document.addEventListener("DOMContentLoaded",function(){const toggler=document.getElementById("theme-toggler");const HTML=document.getElementsByTagName("html")[0];const stored=localStorage.getItem("theme")||"light";HTML.dataset.theme=stored;if(toggler){toggler.checked=stored==="dark";toggler.addEventListener("click",()=>{const newTheme=toggler.checked?"dark":"light";HTML.dataset.theme=newTheme;localStorage.setItem("theme",newTheme)})}const langBtn=document.getElementById("language-dropdown-menu-button");const langMenu=document.getElementById("language-dropdown-menu");if(langBtn&&langMenu){const closeLang=()=>{langMenu.classList.add("hidden");langBtn.setAttribute("aria-expanded","false")};langBtn.addEventListener("click",e=>{e.stopPropagation();langMenu.classList.toggle("hidden");langBtn.setAttribute("aria-expanded",langMenu.classList.contains("hidden")?"false":"true")});document.addEventListener("click",e=>{if(!langMenu.contains(e.target)&&!langBtn.contains(e.target))closeLang()});document.addEventListener("keydown",e=>{if(e.key==="Escape")closeLang()})}});
